/**
 * All corner symbols combined
 */
export const CORNER_SYMBOLS: CornerSymbol[] = [
  ...GEOMETRIC_SYMBOLS,
  ...DECORATIVE_SYMBOLS,
  ...TECH_SYMBOLS,
  ...NATURE_SYMBOLS,
];

/**
 * Get symbols by category
 */
export function getSymbolsByCategory(category: CornerSymbol['category']): CornerSymbol[] {
  return CORNER_SYMBOLS.filter((symbol) => symbol.category === category);
}

/**
 * Get symbol by ID
 */
export function getSymbolById(id: string): CornerSymbol | undefined {
  return CORNER_SYMBOLS.find((symbol) => symbol.id === id);
}

