import { IconConfig } from '@/types/icons';
import { SOCIAL_ICONS } from './social';
import { REACTION_ICONS } from './reactions';
import { UI_ICONS } from './ui';

export interface IconProps {
  name: string;
  size?: number;
  color?: string;
  variant?: 'filled' | 'outline';
  className?: string;
  style?: React.CSSProperties;
}

export const ICON_REGISTRY: Record<string, IconConfig> = {
  // Social icons
  ...SOCIAL_ICONS,
  // Reaction icons
  ...REACTION_ICONS,
  // UI icons
  ...UI_ICONS,
};

export function getIcon(name: string): IconConfig | undefined {
  return ICON_REGISTRY[name];
}

export function getSocialIcons(): IconConfig[] {
  return Object.values(SOCIAL_ICONS);
}

export function getReactionIcons(): IconConfig[] {
  return Object.values(REACTION_ICONS);
}

export function getUIIcons(): IconConfig[] {
  return Object.values(UI_ICONS);
}