/**
 * Get decorator preset by ID
 */
export function getDecoratorPreset(id: string): DecoratorPreset | undefined {
  return DECORATOR_PRESETS.find((preset) => preset.id === id);
}

/**
 * Apply decorator preset to current configuration
 * Returns a new configuration with the preset applied
 */
export function applyDecoratorPreset(
  currentConfig: Partial<DecoratorConfig>,
  presetId: string
): Partial<DecoratorConfig> {
  const preset = getDecoratorPreset(presetId);

  if (!preset) {
    console.warn(`Decorator preset "${presetId}" not found`);
    return currentConfig;
  }

  // Merge preset with current config (preset takes precedence for defined values)
  // We preserve the structure of currentConfig and override with preset values
  const result: Partial<DecoratorConfig> = {
    ...currentConfig,
    ...preset.config,
  };

  return result;
}

/**
 * Get presets by category
 */
export function getPresetsByCategory(category: DecoratorPreset['category']): DecoratorPreset[] {
  return DECORATOR_PRESETS.filter((preset) => preset.category === category);
}