/**
 * Get decorator configuration for a pillar
 *
 * @param pillarId - The pillar ID
 * @returns The decorator configuration for the pillar
 */
export function getPillarDecoratorConfig(pillarId: PillarId): DecoratorConfig {
  return PILLAR_DECORATOR_CONFIG[pillarId] || DEFAULT_DECORATOR_CONFIG;
}

