// ============================================================================
// SUB-TYPE REGISTRY
// ============================================================================

/**
 * All slide sub-types organized by slide type
 */
export const slideSubTypes: Record<SlideType, SlideSubType[]> = {
  title: [titleClassic, titleLarge, titleMinimal, titleStatement, titleHero],
  content: [contentStandard, contentTwoColumn, contentSidebar, contentCard],
  bullets: [bulletsVertical, bulletsHorizontal, bulletsGrid, bulletsNumbered],
  quote: [quoteClassic, quoteLarge, quotePullout],
  cta: [ctaStandard, ctaMinimal, ctaLarge],
  custom: [contentStandard], // Custom uses content sub-types
  image: [
    imageFullBleed,
    imageHalfLeft,
    imageHalfRight,
    imageCard,
    imageGradient,
    imageFrame,
    imagePolaroid,
    imageDiagonalSplit,
    imageMasonry2,
    imageMasonry3,
  ],
};

/**
 * Flat array of all sub-types for easy iteration
 */
export const allSubTypes: SlideSubType[] = Object.values(slideSubTypes).flat();

/**
 * Map of sub-type ID to sub-type configuration
 */
export const subTypeMap: Record<string, SlideSubType> = allSubTypes.reduce(
  (map, subType) => {
    map[subType.id] = subType;
    return map;
  },
  {} as Record<string, SlideSubType>
);

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

/**
 * Get a sub-type by ID
 *
 * @param subTypeId - The sub-type ID (e.g., 'title-classic')
 * @returns The sub-type configuration or undefined if not found
 *
 * @example
 * const subType = getSubType('title-classic');
 * console.log(subType.name); // 'Classic Title'
 */
export function getSubType(subTypeId: string): SlideSubType | undefined {
  return subTypeMap[subTypeId];
}

/**
 * Get all sub-types for a specific slide type
 *
 * @param slideType - The slide type
 * @returns Array of sub-types for the given slide type
 *
 * @example
 * const titleSubTypes = getSubTypesForSlideType('title');
 * console.log(titleSubTypes.length); // 5
 */
export function getSubTypesForSlideType(slideType: SlideType): SlideSubType[] {
  return slideSubTypes[slideType] || [];
}

/**
 * Get the default sub-type for a slide type
 *
 * @param slideType - The slide type
 * @returns The default sub-type or undefined if not found
 *
 * @example
 * const defaultSubType = getDefaultSubType('title');
 * console.log(defaultSubType.id); // 'title-classic'
 */
export function getDefaultSubType(slideType: SlideType): SlideSubType | undefined {
  const subTypes = getSubTypesForSlideType(slideType);
  return subTypes.find((st) => st.isDefault) || subTypes[0];
}

/**
 * Get sub-type ID for a slide type (convenience function)
 *
 * @param slideType - The slide type
 * @returns The default sub-type ID or undefined if not found
 *
 * @example
 * const subTypeId = getDefaultSubTypeId('title');
 * console.log(subTypeId); // 'title-classic'
 */
export function getDefaultSubTypeId(slideType: SlideType): string | undefined {
  return getDefaultSubType(slideType)?.id;
}

/**
 * Check if a sub-type exists
 *
 * @param subTypeId - The sub-type ID
 * @returns True if the sub-type exists
 *
 * @example
 * if (hasSubType('title-classic')) {
 *   // Sub-type exists
 * }
 */
export function hasSubType(subTypeId: string): boolean {
  return subTypeId in subTypeMap;
}

/**
 * Get sub-types by tags
 *
 * @param tags - Array of tags to filter by
 * @returns Array of sub-types matching the tags
 *
 * @example
 * const minimalSubTypes = getSubTypesByTags(['minimal']);
 * console.log(minimalSubTypes.length);
 */
export function getSubTypesByTags(tags: string[]): SlideSubType[] {
  return allSubTypes.filter((subType) =>
    tags.some((tag) => subType.tags?.includes(tag))
  );
}

/**
 * Search sub-types by name or description
 *
 * @param query - Search query
 * @returns Array of matching sub-types
 *
 * @example
 * const results = searchSubTypes('minimal');
 * console.log(results.length);
 */
export function searchSubTypes(query: string): SlideSubType[] {
  const lowerQuery = query.toLowerCase();
  return allSubTypes.filter(
    (subType) =>
      subType.name.toLowerCase().includes(lowerQuery) ||
      subType.description.toLowerCase().includes(lowerQuery) ||
      subType.id.toLowerCase().includes(lowerQuery)
  );
}

/**
 * Get sub-types compatible with a style template
 *
 * @param templateId - The style template ID
 * @returns Array of compatible sub-types
 *
 * @example
 * const compatible = getSubTypesForTemplate('minimal');
 * console.log(compatible.length);
 */
export function getSubTypesForTemplate(templateId: StyleTemplateId): SlideSubType[] {
  return allSubTypes.filter((subType) => {
    if (!subType.compatibleWith || subType.compatibleWith.length === 0) {
      return true; // Compatible with all templates
    }
    return subType.compatibleWith.includes(templateId);
  });
}

